import{organisationLevels,levelNames,digestiveStops,digestiveIndex,enzymeState}from './organisation-models.js?v=20261023-physicscomplete01';
const wrap=(label,body)=>`<svg class="shell-diagram" viewBox="0 0 480 350" role="img" aria-label="${label}">${body}</svg>`;
const txt=(x,y,t,size=14)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${size}">${t}</text>`;
export function organisationFigure(level='cell',{count=1,layers=[]}={}){const index=Math.max(0,organisationLevels.indexOf(level));if(index<2)return wrap(levelNames[level],Array.from({length:level==='cell'?1:count},(_,i)=>`<g transform="translate(${level==='cell'?240:95+(i%3)*140} ${level==='cell'?155:110+Math.floor(i/3)*100})"><ellipse rx="57" ry="22" fill="#ed8b78" stroke="#f8f6f2"/><circle r="8" fill="#182e44"/>${txt(0,44,'Muscle cell',12)}</g>`).join('')+txt(240,325,level==='cell'?'One specialised cell':'Similar cells with a shared function'));if(index===2)return wrap('Stomach organ with '+layers.join(', ')+' tissue layers',`<path d="M220 45V100Q320 50 335 160Q360 250 240 285Q120 290 145 225Q170 190 210 175V45" fill="#b7c8d6" fill-opacity=".15" stroke="#f8f6f2" stroke-width="3"/>${layers.map((layer,i)=>`<path d="M${170+i*17} 215Q${240+i*10} ${295-i*22} ${310-i*15} 170" fill="none" stroke="${['#ed8b78','#d4dfe7','#91a5b3'][i]}" stroke-width="10"/>${txt(240,40+i*25,{muscle:'Muscle tissue',lining:'Epithelial lining',gland:'Glandular tissue'}[layer],12)}`).join('')}`);return wrap(levelNames[level],organisationLevels.map((k,i)=>`<rect x="${50+i*12}" y="${20+i*58}" width="${380-i*24}" height="44" rx="12" fill="${k===level?'#ed8b78':'#b7c8d6'}" fill-opacity=".3" stroke="#f8f6f2"/>${txt(240,48+i*58,levelNames[k])}`).join(''));}
export function digestiveFigure(step=0,{phase='route',small=false,cross=0,assessment=false}={}){step=digestiveIndex(step);if(phase==='absorb'){const x=small?70+cross*90:Math.min(190,70+cross*90);return wrap('Gut lumen and blood separated by intestinal lining. '+(small?'Small soluble molecules':'Large insoluble molecule')+(cross===3&&small?' reach the blood.':'.'),`<rect x="25" y="50" width="200" height="210" rx="20" fill="#b7c8d6" fill-opacity=".12"/><rect x="255" y="50" width="200" height="210" rx="20" fill="#ed8b78" fill-opacity=".12"/><path d="M232 50V260M248 50V260" stroke="#f8f6f2" stroke-width="3"/>${txt(120,30,'Gut contents')}${txt(355,30,'Blood')}${small?`<circle cx="${x}" cy="150" r="12" fill="#ed8b78"/>`:`<path d="M${x-30} 150H${x+30}" stroke="#ed8b78" stroke-width="14"/>`}${txt(240,310,small?'Small soluble products can be absorbed':'Large insoluble food cannot cross intact',13)}`);}const s=digestiveStops[step];return wrap('Schematic digestive tract; selected '+s.name,`<path d="M185 10Q135 30 125 90L105 285Q240 345 375 285L355 90Q345 30 295 10" fill="#b7c8d6" fill-opacity=".05" stroke="#b7c8d6" opacity=".5"/><path d="M240 30V95Q300 80 320 125Q340 165 275 172" stroke="#ed8b78" stroke-width="18" fill="none"/><path d="M275 172Q190 168 190 195Q295 185 295 213Q185 208 190 235Q290 225 280 255" stroke="#d4dfe7" stroke-width="12" fill="none"/><path d="M280 255Q340 260 335 165Q340 145 315 145M190 155Q145 145 145 175V265Q145 285 240 280V315" stroke="#91a5b3" stroke-width="17" fill="none"/><circle cx="${s.x}" cy="${s.y}" r="10" fill="#ed8b78" stroke="#f8f6f2" stroke-width="3"/>${txt(240,340,s.name,15)}`);}
export function enzymeFigure(substrate='fit',step=0){const f=enzymeState(substrate,step),x=[350,315,250,350][f.step];return wrap('Schematic enzyme; '+(!f.fit?'substrate does not fit':f.products?'two products released; enzyme remains unchanged':f.bound?'substrate bound at active site':'substrate approaching'),`<path d="M85 75Q20 175 85 275H250V220L195 175L250 130V75Z" fill="#91a5b3" stroke="#f8f6f2" stroke-width="3"/>${txt(125,185,'Enzyme',16)}${f.products?`<path d="M330 135L370 165H330Z" fill="#ed8b78"/><path d="M330 205L370 175H330Z" fill="#ed8b78"/>${txt(350,260,'Products')}`:f.fit?`<path d="M${x} 130L${x-55} 175L${x} 220Z" fill="#ed8b78" stroke="#f8f6f2" stroke-width="2"/>${txt(x,260,'Substrate')}`:`<circle cx="${x}" cy="175" r="37" fill="#ed8b78" stroke="#f8f6f2"/>${txt(x,260,'Different shape')}`}${txt(240,330,'Shape analogy · not a molecular structure',12)}`);}
